-- Historical values and states are read as persisted, never regenerated.
create function public.get_checkin_plan_proposal(p_checkin_id uuid)
returns jsonb language plpgsql stable security invoker set search_path = '' as $$
declare
  v_checkin jsonb;
  v_plan_id uuid;
  v_revision integer;
  v_plan jsonb;
begin
  -- Existing invoker RPC supplies the same not-found result for foreign IDs.
  v_checkin := public.get_weekly_checkin(p_checkin_id);
  if v_checkin ->> 'plan_proposal_id' is null then
    if v_checkin ->> 'status' = 'open' then return null; end if;
    raise exception 'check-in proposal is not recoverable' using errcode = 'PT409';
  end if;
  select revision.plan_id, revision.revision_number
  into v_plan_id, v_revision
  from public.change_proposals proposal
  join public.plan_revisions revision
    on revision.id = proposal.target_plan_revision_id
   and revision.athlete_id = proposal.athlete_id
  join public.weekly_checkins checkin
    on checkin.id = revision.checkin_id
   and checkin.athlete_id = revision.athlete_id
   and checkin.plan_proposal_id = proposal.id
  where checkin.id = p_checkin_id
    and checkin.athlete_id = (select auth.uid())
    and checkin.status = 'completed'
    and proposal.kind = 'plan_revision';
  if not found then
    raise exception 'check-in proposal is not recoverable' using errcode = 'PT409';
  end if;
  v_plan := public.get_weekly_plan(v_plan_id, v_revision);
  if v_plan #>> '{proposal,id}' is distinct from v_checkin ->> 'plan_proposal_id' then
    raise exception 'check-in proposal is not recoverable' using errcode = 'PT409';
  end if;
  return jsonb_build_object('plan', v_plan, 'proposal', v_plan -> 'proposal');
end;
$$;
revoke all on function public.get_checkin_plan_proposal(uuid)
  from public, anon, authenticated, service_role;
grant execute on function public.get_checkin_plan_proposal(uuid) to authenticated;

create or replace function public.create_weekly_plan_proposal_v3(
  p_athlete_id uuid, p_payload jsonb
)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_result jsonb;
  v_checkin_id uuid := nullif(p_payload ->> 'checkin_id', '')::uuid;
  v_checkin public.weekly_checkins%rowtype;
  v_existing_count integer;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'trusted backend authorization required' using errcode = '42501';
  end if;
  if v_checkin_id is not null then
    -- Serialize before creating any plan/revision. Creation plus attachment
    -- commits or rolls back together, including all nested v2 writes.
    select * into v_checkin from public.weekly_checkins
    where id = v_checkin_id and athlete_id = p_athlete_id for update;
    if not found then
      raise exception 'weekly check-in not found' using errcode = 'P0002';
    end if;
    if v_checkin.plan_proposal_id is not null then
      select jsonb_build_object('plan_id', revision.plan_id,
        'revision', revision.revision_number, 'proposal_id', proposal.id)
      into v_result
      from public.change_proposals proposal
      join public.plan_revisions revision
        on revision.id = proposal.target_plan_revision_id
       and revision.athlete_id = proposal.athlete_id
      where proposal.id = v_checkin.plan_proposal_id
        and proposal.athlete_id = p_athlete_id
        and proposal.kind = 'plan_revision'
        and revision.checkin_id = v_checkin_id;
      if v_result is null then
        raise exception 'check-in proposal is not recoverable' using errcode = 'PT409';
      end if;
      return v_result;
    end if;
    if v_checkin.status <> 'open' then
      raise exception 'check-in proposal is not recoverable' using errcode = 'PT409';
    end if;
    -- Compatibility with a pre-A5 commit between persistence and attachment.
    -- Only an unambiguous owned revision can be recovered; terminal state stays.
    select count(*) into v_existing_count
    from public.plan_revisions revision
    join public.change_proposals proposal on proposal.target_plan_revision_id = revision.id
      and proposal.athlete_id = revision.athlete_id
    where revision.checkin_id = v_checkin_id and revision.athlete_id = p_athlete_id
      and proposal.kind = 'plan_revision';
    if v_existing_count > 1 then
      raise exception 'check-in proposal is not recoverable' using errcode = 'PT409';
    elsif v_existing_count = 1 then
      select jsonb_build_object('plan_id', revision.plan_id,
        'revision', revision.revision_number, 'proposal_id', proposal.id)
      into v_result
      from public.plan_revisions revision
      join public.change_proposals proposal on proposal.target_plan_revision_id = revision.id
        and proposal.athlete_id = revision.athlete_id
      where revision.checkin_id = v_checkin_id and revision.athlete_id = p_athlete_id
      and proposal.kind = 'plan_revision';
      perform public.attach_checkin_plan_proposal(p_athlete_id, v_checkin_id,
        (v_result ->> 'proposal_id')::uuid);
      return v_result;
    end if;
  end if;
  if p_payload ->> 'ruleset_version' <> 'phase-13-joren-ruleset-1'
     or p_payload ->> 'planning_ruleset_version' <>
       'joren-planning-ruleset-2' then
    raise exception 'planning ruleset provenance is invalid'
      using errcode = '23514';
  end if;
  if jsonb_typeof(coalesce(p_payload -> 'cross_training_opt_ins', '[]'::jsonb))
     <> 'array' then
    raise exception 'cross-training choice is invalid' using errcode = '23514';
  end if;
  v_result := public.create_weekly_plan_proposal_v2(p_athlete_id, p_payload);
  perform set_config('start23.critical_write', 'on', true);
  update public.plan_revisions
  set planning_ruleset_version = 'joren-planning-ruleset-2',
      cross_training_opt_ins = array(
        select jsonb_array_elements_text(
          coalesce(p_payload -> 'cross_training_opt_ins', '[]'::jsonb)
        )
      )
  where plan_id = (v_result ->> 'plan_id')::uuid
    and athlete_id = p_athlete_id
    and revision_number = (v_result ->> 'revision')::integer
    and (planning_ruleset_version is null
      or planning_ruleset_version = 'joren-planning-ruleset-2');
  if not found then
    raise exception 'planning revision provenance is invalid'
      using errcode = '23514';
  end if;
  if v_checkin_id is not null then
    perform public.attach_checkin_plan_proposal(p_athlete_id, v_checkin_id,
      (v_result ->> 'proposal_id')::uuid);
  end if;
  return v_result;
end;
$$;
revoke all on function public.create_weekly_plan_proposal_v3(uuid, jsonb)
  from public, anon, authenticated, service_role;
grant execute on function public.create_weekly_plan_proposal_v3(uuid, jsonb)
  to service_role;

$readiness_20261026224844$]);

-- Exact delta only: no anonymous exception; removed historical rights also STOP.
create temporary table readiness_client_execute_after on commit drop as
select replace(n.nspname||'.'||p.proname||'('||
  oidvectortypes(p.proargtypes)||')',' ','') as signature,
role_name from pg_proc p join pg_namespace n on n.oid=p.pronamespace
cross join (values ('anon'),('authenticated')) roles(role_name)
where n.nspname in ('public','private') and p.prokind='f'
and has_function_privilege(role_name,p.oid,'EXECUTE');
do $exact_execute$ begin
if exists(select 1 from readiness_client_execute_after a
  where not exists(select 1 from readiness_client_execute_before b
    where b.signature=a.signature and b.role_name=a.role_name)
  and (a.role_name<>'authenticated' or not a.signature in
    (select jsonb_array_elements_text('["public.get_checkin_plan_proposal(uuid)"]'::jsonb))))
or exists(select 1 from readiness_client_execute_before b
  where not exists(select 1 from readiness_client_execute_after a
    where a.signature=b.signature and a.role_name=b.role_name))
or exists(select 1 from jsonb_array_elements_text('["public.get_checkin_plan_proposal(uuid)"]'::jsonb) e(signature)
  where not exists(select 1 from readiness_client_execute_after a
    where a.signature=e.signature and a.role_name='authenticated'))
then raise exception 'Unexpected client EXECUTE delta; exact approval required';
end if;
end; $exact_execute$;

create temporary table readiness_service_after on commit drop as
select replace(n.nspname||'.'||p.proname||'('||
  oidvectortypes(p.proargtypes)||')',' ','') as signature
from pg_proc p join pg_namespace n on n.oid=p.pronamespace
where n.nspname in ('public','private') and p.prokind='f'
and has_function_privilege('service_role',p.oid,'EXECUTE');
create temporary table readiness_tables_after on commit drop as
select n.nspname,c.relname,role_name,privilege
from pg_class c join pg_namespace n on n.oid=c.relnamespace
cross join (values('anon'),('authenticated'),('service_role')) roles(role_name)
cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),
 ('REFERENCES'),('TRIGGER'),('MAINTAIN')) privileges(privilege)
where n.nspname in ('public','private') and c.relkind in ('r','v')
and has_table_privilege(role_name,c.oid,privilege);
create temporary table readiness_defaults_after on commit drop as
select r.rolname,n.nspname,d.defaclobjtype,a.grantee,
 a.privilege_type,a.is_grantable
from pg_default_acl d join pg_roles r on r.oid=d.defaclrole
left join pg_namespace n on n.oid=d.defaclnamespace
cross join lateral aclexplode(d.defaclacl) a;
create temporary table readiness_role_powers_after on commit drop as
select rolname,rolsuper,rolinherit,rolcreaterole,rolcreatedb,rolcanlogin,
 rolreplication,rolbypassrls from pg_roles
where rolname in ('anon','authenticated','service_role');
create temporary table readiness_memberships_after on commit drop as
select role.rolname as granted_role,member.rolname as member,
 grantor.rolname as grantor,m.admin_option,m.inherit_option,m.set_option
from pg_auth_members m join pg_roles role on role.oid=m.roleid
join pg_roles member on member.oid=m.member
join pg_roles grantor on grantor.oid=m.grantor;
create temporary table readiness_schemas_after on commit drop as
select n.nspname,role_name,has_schema_privilege(role_name,n.oid,'USAGE') as usage,
 has_schema_privilege(role_name,n.oid,'CREATE') as creation
from pg_namespace n
cross join (values('anon'),('authenticated'),('service_role')) roles(role_name)
where n.nspname in ('public','private');

do $infrastructure$ begin
if exists(select * from readiness_role_powers_before
 except select * from readiness_role_powers_after)
or exists(select * from readiness_role_powers_after
 except select * from readiness_role_powers_before)
or exists(select * from readiness_memberships_before
 except select * from readiness_memberships_after)
or exists(select * from readiness_memberships_after
 except select * from readiness_memberships_before) then
 raise exception 'Unexpected role powers or membership'; end if;
if exists(select * from readiness_schemas_before
 except select * from readiness_schemas_after)
or exists(select * from readiness_schemas_after
 except select * from readiness_schemas_before) then
 raise exception 'Unexpected application schema authority'; end if;
if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 cross join lateral aclexplode(p.proacl) a
 where n.nspname in ('public','private') and a.is_grantable
 and pg_get_userbyid(a.grantee) in ('anon','authenticated','service_role'))
or exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
 cross join lateral aclexplode(c.relacl) a
 where n.nspname in ('public','private') and a.is_grantable
 and pg_get_userbyid(a.grantee) in ('anon','authenticated','service_role'))
or exists(select 1 from pg_namespace n cross join lateral aclexplode(n.nspacl) a
 where n.nspname in ('public','private') and a.is_grantable
 and pg_get_userbyid(a.grantee) in ('anon','authenticated','service_role')) then
 raise exception 'Unreviewed privilege grant options'; end if;
if exists(select signature from readiness_service_after
 except select signature from readiness_service_before
 except select jsonb_array_elements_text('["private.v6_revision_workouts(uuid)", "public.complete_activity_rpe_v2(uuid,uuid,jsonb)", "public.create_v6_frequency_swipe_draft(uuid,jsonb)", "public.create_v6_frequency_swipe_proposal(uuid,jsonb)", "public.create_v6_weekly_plan_proposal(uuid,jsonb)", "public.create_weekly_plan_proposal_v4(uuid,jsonb)", "public.get_activity_processing_context_v2(uuid,uuid)", "public.get_activity_presentation_v2(uuid)", "public.get_inactive_v6_catalog_for_planning()", "public.get_plan_load_history_for_planning_v16(uuid,date)", "public.get_v6_edit_retry(uuid,text)", "public.get_v6_frequency_context(uuid,date,text)", "public.get_v6_mobile_edit_retry(uuid,text)", "public.get_v6_plan_context_for_planning(uuid,uuid,integer)", "public.move_v6_planned_workout(uuid,jsonb)", "public.update_v6_frequency_swipe_draft(uuid,uuid,integer,jsonb)"]'::jsonb))
or exists(select signature from readiness_service_before
 except select signature from readiness_service_after) then
 raise exception 'Unexpected server EXECUTE delta'; end if;
if exists(select * from (select * from readiness_tables_after
 except select * from readiness_tables_before) d where not
 (d.role_name='service_role' and d.nspname='private'
 and d.relname in ('realized_v2_activity_inputs','realized_v2_calculations',
 'workout_registration_events','realized_v2_plan_evidence')
 and d.privilege in ('SELECT','INSERT')))
or exists(select * from (select * from readiness_tables_before
 except select * from readiness_tables_after) d where not
 (d.role_name='service_role' and d.nspname='public'
 and d.relname in ('workout_templates','workout_segments',
 'workout_template_phase_tags','workout_template_zone_requirements')
 and d.privilege in ('TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'))) then
 raise exception 'Unexpected table privilege delta'; end if;
if exists(select * from readiness_defaults_after
 except select * from readiness_defaults_before)
or exists(select * from (select * from readiness_defaults_before
 except select * from readiness_defaults_after) d where not
 (d.rolname='postgres' and d.nspname='public' and d.defaclobjtype='r'
 and pg_get_userbyid(d.grantee) in ('anon','authenticated','service_role')
 and d.privilege_type in ('TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'))) then
 raise exception 'Unexpected default ACL delta'; end if;
end; $infrastructure$;

do $no_enrollment$ declare enrolled boolean; begin
if exists(select 1 from pg_roles where rolname in
 ('v6_frequency_registrar','v6_frequency_test_executor')
 and (rolcanlogin or rolsuper or rolcreatedb or rolcreaterole
      or rolreplication or rolbypassrls)) then
 raise exception 'Unexpected privileged frequency role';
end if;
if exists(select 1 from pg_auth_members m join pg_roles r on r.oid=m.roleid
  where r.rolname in ('v6_frequency_registrar','v6_frequency_test_executor')) then
  raise exception 'Unexpected frequency role membership';
end if;
if to_regclass('private.frequency_reviewers') is not null then
  execute 'select exists(select 1 from private.frequency_reviewers)' into enrolled;
  if enrolled then raise exception 'Unexpected reviewer enrollment'; end if;
end if;
if to_regclass('private.frequency_decisions') is not null then
  execute 'select exists(select 1 from private.frequency_decisions)' into enrolled;
  if enrolled then raise exception 'Unexpected frequency authorization'; end if;
end if;
end; $no_enrollment$;
commit;
